content.text:
{
  "name": "PyMCA/SPEC 数据文件写入器",
  "name_en": "PyMCA/SPEC Data File Writer",
  "manufacturer": "",
  "description": "用于实验扫描数据采集流程的文件写入组件，可生成类似 PyMCA/SPEC 格式的输出文件，写入测量头信息、扫描设备信息和数据点，便于后续分析、可视化与归档。",
  "description_en": "A data-writing component used in experimental scan acquisition workflows. It generates PyMCA/SPEC-like output files, recording measurement headers, scan device information, and data points for later analysis, visualization, and archiving.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭当前输出文件。",
      "description_en": "Close the current output file."
    },
    {
      "action_name": "auto-writeData",
      "description": "将采集到的扫描数据写入输出文件。",
      "description_en": "Write acquired scan data to the output file."
    },
    {
      "action_name": "auto-writeHeader",
      "description": "写入文件头和扫描设备相关信息。",
      "description_en": "Write the file header and scan device information."
    }
  ],
  "tag_hints": [
    "scan data logging",
    "SPEC file format",
    "PyMCA",
    "experimental data export",
    "beamline data acquisition"
  ]
}

